class Embedder:
    def __init__(self, api_key: str, model: str = VOYAGE_MODEL):
        self.client = voyageai.Client(api_key=api_key)
        self.model = model
        self.total_tokens = 0
        self.total_calls = 0

    def embed(self, texts: list[str], input_type: str = "document") -> list[list[float]]:
        """Embed a batch of texts. Max 128 texts per API call. Retries on rate limit."""
        if not texts:
            return []
        import time as _time
        batch_size = 128
        all_vectors = []
        for i in range(0, len(texts), batch_size):
            batch = texts[i : i + batch_size]
            while True:
                try:
                    result = self.client.embed(
                        batch,
                        model=self.model,
                        input_type=input_type,
                    )
                    all_vectors.extend(result.embeddings)
                    self.total_tokens += result.total_tokens
                    self.total_calls += 1
                    break
                except Exception as e:
                    err_str = str(e).lower()
                    if "rate" in err_str or "429" in err_str or "too many" in err_str:
                        wait = 5
                        print(f"    rate limited, polling in {wait}s...", file=sys.stderr)
                        _time.sleep(wait)
                    else:
                        raise
        return all_vectors

    def embed_query(self, text: str) -> list[float]:
        result = self.client.embed([text], model=self.model, input_type="query")
        self.total_tokens += result.total_tokens
        self.total_calls += 1
        return result.embeddings[0]

